import React, { useEffect, useState } from "react";
import {
  ArrowRight,
  BookOpen,
  Eye,
  EyeOff,
  GraduationCap,
  Lock,
  LogIn,
  Mail,
  Shield,
  Sparkles,
  Users,
} from "lucide-react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import toast, { Toaster } from "react-hot-toast";
import { setUserToken } from "../redux/actions";
import { useDispatch } from "react-redux";
import axiosWrapper from "../utils/AxiosWrapper";

const USER_TYPES = {
  STUDENT: "Student",
  FACULTY: "Faculty",
  ADMIN: "Admin",
};

const USER_TYPE_INFO = {
  Student: {
    icon: GraduationCap,
    gradient: "from-blue-600 to-cyan-500",
    chip: "bg-blue-50 text-blue-700 border-blue-200",
    card: "border-blue-200 hover:border-blue-300",
    selectedCard: "ring-blue-500 border-blue-500 bg-blue-50",
    description: "Access your courses, attendance, and grades",
  },
  Faculty: {
    icon: Users,
    gradient: "from-violet-600 to-purple-500",
    chip: "bg-violet-50 text-violet-700 border-violet-200",
    card: "border-violet-200 hover:border-violet-300",
    selectedCard: "ring-violet-500 border-violet-500 bg-violet-50",
    description: "Manage classes, attendance, and marks",
  },
  Admin: {
    icon: Shield,
    gradient: "from-indigo-600 to-blue-600",
    chip: "bg-indigo-50 text-indigo-700 border-indigo-200",
    card: "border-indigo-200 hover:border-indigo-300",
    selectedCard: "ring-indigo-500 border-indigo-500 bg-indigo-50",
    description: "Control users, academics, and operations",
  },
};

const normalizeUserType = (value) => {
  if (!value) return USER_TYPES.STUDENT;
  const wanted = value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
  return USER_TYPE_INFO[wanted] ? wanted : USER_TYPES.STUDENT;
};

const LoginForm = ({
  selected,
  onSubmit,
  formData,
  setFormData,
  isSubmitting,
  showPassword,
  setShowPassword,
}) => {
  const typeInfo = USER_TYPE_INFO[selected];
  const Icon = typeInfo.icon;

  return (
    <form className="w-full space-y-5" onSubmit={onSubmit}>
      <div
        className={`flex items-center gap-3 rounded-xl border px-4 py-3 ${typeInfo.chip}`}
      >
        <Icon size={20} />
        <div>
          <h3 className="text-sm font-semibold">{selected} Login</h3>
          <p className="text-xs opacity-80">{typeInfo.description}</p>
        </div>
      </div>

      <div className="space-y-2">
        <label className="block text-sm font-medium text-gray-700" htmlFor="email">
          Email Address
        </label>
        <div className="relative">
          <Mail
            className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-gray-400"
            size={18}
          />
          <input
            type="email"
            id="email"
            required
            placeholder={`Enter your ${selected.toLowerCase()} email`}
            className="w-full rounded-xl border border-gray-300 py-3 pl-11 pr-4 text-sm outline-none transition focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100"
            value={formData.email}
            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
          />
        </div>
      </div>

      <div className="space-y-2">
        <label className="block text-sm font-medium text-gray-700" htmlFor="password">
          Password
        </label>
        <div className="relative">
          <Lock
            className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-gray-400"
            size={18}
          />
          <input
            type={showPassword ? "text" : "password"}
            id="password"
            required
            placeholder="Enter your password"
            className="w-full rounded-xl border border-gray-300 py-3 pl-11 pr-12 text-sm outline-none transition focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100"
            value={formData.password}
            onChange={(e) => setFormData({ ...formData, password: e.target.value })}
          />
          <button
            type="button"
            aria-label={showPassword ? "Hide password" : "Show password"}
            className="absolute right-3 top-1/2 -translate-y-1/2 rounded-md p-1 text-gray-500 transition hover:bg-gray-100"
            onClick={() => setShowPassword((prev) => !prev)}
          >
            {showPassword ? <EyeOff size={17} /> : <Eye size={17} />}
          </button>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <label className="flex cursor-pointer items-center gap-2">
          <input type="checkbox" className="w-4 h-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500" />
          <span className="text-sm text-gray-600">Remember me</span>
        </label>
        <Link
          className="text-sm font-semibold text-indigo-600 hover:text-indigo-700"
          to="/forget-password"
        >
          Forgot Password?
        </Link>
      </div>

      <button
        type="submit"
        disabled={isSubmitting}
        className={`flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r ${typeInfo.gradient} py-3.5 text-sm font-semibold text-white shadow-lg transition hover:opacity-95 disabled:cursor-not-allowed disabled:opacity-70`}
      >
        {isSubmitting ? "Signing in..." : "Sign In"}
        {!isSubmitting && <ArrowRight size={18} />}
      </button>

      <p className="text-center text-xs text-gray-500">
        Demo access only. Contact admin for account creation.
      </p>
    </form>
  );
};

const UserTypeSelector = ({ selected, onSelect }) => {
  return (
    <div className="grid grid-cols-3 gap-4 mb-8">
      {Object.values(USER_TYPES).map((type) => {
        const info = USER_TYPE_INFO[type];
        const Icon = info.icon;
        const isSelected = selected === type;
        
        return (
          <button
            key={type}
            type="button"
            onClick={() => onSelect(type)}
            className={`flex flex-col items-center gap-2 rounded-xl border px-3 py-4 transition-all duration-200 ${
              isSelected
                ? `ring-2 ${info.selectedCard}`
                : `bg-white text-gray-700 ${info.card}`
            }`}
          >
            <Icon size={22} />
            <span className="text-sm font-semibold">{type}</span>
          </button>
        );
      })}
    </div>
  );
};

const Login = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [searchParams, setSearchParams] = useSearchParams();
  const type = searchParams.get("type");

  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });

  const [selected, setSelected] = useState(() => normalizeUserType(type));
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleUserTypeSelect = (role) => {
    const userType = role.toLowerCase();
    setSelected(role);
    setSearchParams({ type: userType });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.email || !formData.password) {
      toast.error("Please fill in all fields");
      return;
    }

    try {
      setIsSubmitting(true);
      const response = await axiosWrapper.post(
        `/${selected.toLowerCase()}/login`,
        formData,
        {
          headers: { "Content-Type": "application/json" },
        }
      );

      const { token } = response.data.data;
      localStorage.setItem("userToken", token);
      localStorage.setItem("userType", selected);
      dispatch(setUserToken(token));
      navigate(`/${selected.toLowerCase()}`);
    } catch (error) {
      console.error("Login failed:", error);
      toast.error(error.response?.data?.message || "Login failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  useEffect(() => {
    const userToken = localStorage.getItem("userToken");
    if (userToken) {
      navigate(`/${localStorage.getItem("userType").toLowerCase()}`);
    }
  }, [navigate]);

  useEffect(() => {
    setSelected(normalizeUserType(type));
  }, [type]);

  return (
    <div className="relative min-h-screen overflow-hidden bg-slate-950 px-4 py-10">
      <div className="pointer-events-none absolute inset-0">
        <div className="absolute -top-40 left-1/2 h-96 w-96 -translate-x-1/2 rounded-full bg-indigo-600/30 blur-3xl" />
        <div className="absolute bottom-0 left-0 h-80 w-80 rounded-full bg-fuchsia-600/20 blur-3xl" />
        <div className="absolute right-0 top-1/3 h-80 w-80 rounded-full bg-cyan-600/20 blur-3xl" />
      </div>

      <div className="relative mx-auto grid w-full max-w-6xl items-center gap-8 lg:grid-cols-2">
        <section className="hidden rounded-3xl border border-white/10 bg-white/5 p-8 text-white shadow-2xl backdrop-blur-xl lg:block">
          <div className="mb-6 inline-flex items-center gap-3 rounded-full border border-white/15 bg-white/10 px-4 py-2 text-sm">
            <Sparkles size={16} />
            Smart Campus Portal
          </div>

          <h1 className="text-5xl font-bold leading-tight">
            Welcome to
            <span className="block bg-gradient-to-r from-cyan-300 to-indigo-300 bg-clip-text text-transparent">
              College ERP
            </span>
          </h1>

          <p className="mt-5 text-white/80">
            One place for students, faculty, and admins to manage academics,
            attendance, and communication.
          </p>

          <div className="mt-8 grid grid-cols-3 gap-3">
            <div className="rounded-2xl border border-white/10 bg-white/10 p-4">
              <Users size={24} className="mb-3 text-cyan-200" />
              <p className="text-xs text-white/70">Users</p>
              <p className="text-lg font-semibold">3 Roles</p>
            </div>
            <div className="rounded-2xl border border-white/10 bg-white/10 p-4">
              <BookOpen size={24} className="mb-3 text-indigo-200" />
              <p className="text-xs text-white/70">Modules</p>
              <p className="text-lg font-semibold">Academics</p>
            </div>
            <div className="rounded-2xl border border-white/10 bg-white/10 p-4">
              <LogIn size={24} className="mb-3 text-fuchsia-200" />
              <p className="text-xs text-white/70">Access</p>
              <p className="text-lg font-semibold">Secure</p>
            </div>
          </div>
        </section>

        <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-2xl sm:p-8 lg:p-10">
          <div className="mb-7 text-center">
            <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-r from-indigo-600 to-violet-600 text-white">
              <GraduationCap size={26} />
            </div>
            <h2 className="text-3xl font-bold text-slate-900">Sign in</h2>
            <p className="mt-1 text-sm text-slate-500">
              Choose your role to continue
            </p>
          </div>

          <UserTypeSelector
            selected={selected}
            onSelect={handleUserTypeSelect}
          />

          <LoginForm
            selected={selected}
            onSubmit={handleSubmit}
            formData={formData}
            setFormData={setFormData}
            isSubmitting={isSubmitting}
            showPassword={showPassword}
            setShowPassword={setShowPassword}
          />
        </section>
      </div>

      <Toaster position="top-center" />
    </div>
  );
};

export default Login;

